-- M-01：仅补齐算力建模元数据，不改业务表、不添加映射、不改变概念发布状态。
-- 来源及逐字段说明见 docs/A800-compute-ontology-checklist.md。

UPDATE bm_concept SET definition = '纳管的物理服务器，包含卡组并提供共享内存和存储容量；当前仅一台八卡 A800。资产容量与实时水位分别登记，不将监控状态当作平台预留。', owner = '运维' WHERE code = 'COMPUTE_NODE' AND domain_code = 'COMPUTE';
UPDATE bm_concept SET definition = '整组预留、持有、抢占和释放的单位。当前 A/B/C/FLEX 四组；实际持有与待生效预留可同时存在；组内未使用卡随组保留，不独立外借。', owner = '运维' WHERE code = 'COMPUTE_GPU_GROUP' AND domain_code = 'COMPUTE';
UPDATE bm_concept SET definition = '卡组中的单张 GPU。以 GPU UUID 稳定识别，节点 ID 与本地卡号标明当前位置。资产显存容量与运行健康来自不同来源，不能仅凭无进程就判定可分配。', owner = '运维' WHERE code = 'COMPUTE_GPU_DEVICE' AND domain_code = 'COMPUTE';
UPDATE bm_concept SET definition = '持续提供服务的模型实例，与一次训练作业不同。可按授权暂停，恢复使用已固定的部署修订配置；单卡模型 C 默认保留。当前每组最多一个未退役部署。', owner = '模型负责人' WHERE code = 'COMPUTE_DEPLOYMENT' AND domain_code = 'COMPUTE';
UPDATE bm_concept SET definition = '员工提出的一次资源需求，记录项目、期望任务类型与规格。通过、排队或拒绝是决策结果；申请可以对应多次历史作业，但同一时刻最多一个活跃作业。', owner = '平台' WHERE code = 'COMPUTE_REQUEST' AND domain_code = 'COMPUTE';
UPDATE bm_concept SET definition = '申请产生的一次实际执行尝试，区别于申请和长期运行的常驻部署。重试创建新作业；一次作业最多一份分配，训练作业不可被其他作业抢占。', owner = '平台' WHERE code = 'COMPUTE_JOB' AND domain_code = 'COMPUTE';
UPDATE bm_concept SET definition = '一次作业对整组资源的绑定与预留，保存预留容量及时间。PENDING 是待生效预留，只有 OCCUPIED 才通过持有区间取得卡组；组内未使用卡不外借。', owner = '平台' WHERE code = 'COMPUTE_ALLOCATION' AND domain_code = 'COMPUTE';
UPDATE bm_concept SET definition = '记录谁从何时到何时实际持有卡组，持有主体恰好是常驻部署或占用分配之一。待生效预留不创建持有；主体、卡组和开始时间不可变，结束时间只能写一次，关闭后不可变。', owner = '平台' WHERE code = 'COMPUTE_HOLD_PERIOD' AND domain_code = 'COMPUTE';
UPDATE bm_concept SET definition = '定义检查、规划、动作或条件写入的模板，不是某次执行结果。BeModel 的 bm_rule 管定义，算力 rule_version 存执行快照；规则编号与版本组合识别一次规则版本。', owner = '规则负责人' WHERE code = 'COMPUTE_RULE' AND domain_code = 'COMPUTE';
UPDATE bm_concept SET definition = '某条指定版本规则在一次决策中的执行结果。result 表示规则是否通过，output 保存结构化产出；不能用规则是否通过代替申请结论或动作执行状态。', owner = '平台' WHERE code = 'COMPUTE_RULE_CHECK' AND domain_code = 'COMPUTE';
UPDATE bm_concept SET definition = '对申请的一次阶段性判断，区分准入、提交和收尾。通过规则检查及预留成功才能批准，但批准不等于动作或作业启动成功；重判保留前序、替代关系与原证据。', owner = '平台' WHERE code = 'COMPUTE_DECISION' AND domain_code = 'COMPUTE';
UPDATE bm_concept SET definition = '一次实际操作，例如通知、摘流、停服、启动和恢复。execution_action 是运行记录，区别于 bm_action 的动作定义；幂等编号、执行状态和回执用于核对是否真正完成。', owner = '平台' WHERE code = 'COMPUTE_ACTION' AND domain_code = 'COMPUTE';
UPDATE bm_concept SET definition = '一次判定采用的数据及其来源、采集时间和有效期。通过快照集合关联决策，保留来源引用与关键值；不能事后用最新监控覆盖历史证据。', owner = '平台' WHERE code = 'COMPUTE_EVIDENCE' AND domain_code = 'COMPUTE';
UPDATE bm_concept SET definition = '已经发生的资源变化或通知事实，来自决策、监控、硬件或执行器。事件不是操作指令；来源决策可为空，事件触发决策与决策产生事件是不同方向的关系。', owner = '平台' WHERE code = 'COMPUTE_EVENT' AND domain_code = 'COMPUTE';
UPDATE bm_concept SET definition = '以公司员工编号识别的申请人和通知对象，归属团队。当前 Demo 只登记基本信息，账号绑定、角色和部门不等于已实现的员工权限模型。', owner = '身份数据维护人' WHERE code = 'COMPUTE_EMPLOYEE' AND domain_code = 'COMPUTE';
UPDATE bm_concept SET definition = '员工所属和项目参与的组织单元；可作为部署责任与通知对象。当前团队与项目使用关联表，团队类型尚未登记。', owner = '组织数据维护人' WHERE code = 'COMPUTE_TEAM' AND domain_code = 'COMPUTE';
UPDATE bm_concept SET definition = '资源使用与成本归属的项目，记录负责人、团队和成本中心。v0.7 当前不设配额，不因项目额度拦截申请；用量由作业和分配汇总。', owner = '项目负责人' WHERE code = 'COMPUTE_PROJECT' AND domain_code = 'COMPUTE';
UPDATE bm_concept SET definition = '任务模板，给出默认等级和资源规格；不是实际作业，也不是某个常驻模型。申请指定期望类型，作业记录实际类型，变更须有改派依据。', owner = '规则负责人' WHERE code = 'COMPUTE_TASK_TYPE' AND domain_code = 'COMPUTE';

ON DUPLICATE KEY UPDATE attr_name = VALUES(attr_name), data_type = VALUES(data_type),
    is_key = VALUES(is_key), definition = VALUES(definition), sort = VALUES(sort);
