INSERT INTO bm_attribute (concept_code, attr_code, attr_name, data_type, is_key, definition, sort) VALUES
('COMPUTE_NODE', 'IDENTIFIER', '节点稳定编号', 'STRING', 1, '已有字段：compute_node.node_key；节点稳定编号，唯一，不等于可变主机名。', 10),
('COMPUTE_NODE', 'HOSTNAME', '主机名', 'STRING', 0, '已有字段：compute_node.hostname；资产登记的主机名。', 20),
('COMPUTE_NODE', 'MEMORY_CAPACITY_BYTES', '内存总容量', 'BIGINT', 0, '已有字段：compute_node.memory_capacity_bytes；单位字节，非负。', 30),
('COMPUTE_NODE', 'MEMORY_RESERVED_BYTES', '系统保留内存', 'BIGINT', 0, '已有字段：compute_node.memory_reserved_bytes；单位字节，非负，不用于任务分配。', 40),
('COMPUTE_NODE', 'TEMPORARY_CAPACITY_BYTES', '临时存储容量', 'BIGINT', 0, '已有字段：compute_node.temporary_capacity_bytes；单位字节，非负。', 50),
('COMPUTE_NODE', 'PERSISTENT_CAPACITY_BYTES', '持久存储容量', 'BIGINT', 0, '已有字段：compute_node.persistent_capacity_bytes；单位字节，非负。', 60),
('COMPUTE_NODE', 'RESOURCE_WATERMARK', '内存与磁盘水位', 'JSON', 0, '关联查询：resource_observation.values_json，subject_kind=NODE；实时值须带单位、来源与采集时间，尚无真实采集。', 70),
('COMPUTE_NODE', 'OBSERVED_AT', '最近采集时间', 'DATE', 0, '关联查询：resource_observation.observed_at；UTC，不能用接收时间代替采集时间。', 80),
('COMPUTE_NODE', 'IP_ADDRESS', '节点地址', 'STRING', 0, '尚未落库：v0.7 的 IP 地址；当前 compute_node 没有对应列。', 90),
('COMPUTE_NODE', 'MANAGEMENT_STATUS', '纳管状态', 'ENUM', 0, '尚未落库：节点是否纳管；不等于概念的 DRAFT/REVIEW/PUBLISHED/DEPRECATED。', 100),
('COMPUTE_GPU_GROUP', 'IDENTIFIER', '节点内卡组编号', 'STRING', 0, '已有字段：gpu_group.group_code；仅与 node_id 组合唯一，不能单独当全局主键。', 10),
('COMPUTE_GPU_GROUP', 'GROUP_ID', '卡组记录编号', 'BIGINT', 1, '已有字段：gpu_group.id；全局记录主键。', 20),
('COMPUTE_GPU_GROUP', 'NAME', '卡组名称', 'STRING', 0, '已有字段：gpu_group.group_code；Demo 以组编号展示名称，无独立名称列。', 30),
('COMPUTE_GPU_GROUP', 'CURRENT_HOLDER', '当前持有者', 'JSON', 0, '关联查询：gpu_group.current_hold_id → hold_period；主体为部署或占用分配，两者恰选一个；不是待生效预留。', 40),
('COMPUTE_GPU_GROUP', 'PENDING_RESERVATION', '待生效预留', 'JSON', 0, '关联查询：gpu_group.pending_allocation_id → gpu_allocation；PENDING 只留资源，尚未取得持有权。', 50),
('COMPUTE_GPU_GROUP', 'STATUS', '卡组业务状态', 'ENUM', 0, '派生结果：根据持有、待生效预留和观测组合解释；可能同时为已持有和已预留，不维护单一状态列，也不是概念发布状态。', 60),
('COMPUTE_GPU_GROUP', 'DIRECTLY_ALLOCATABLE', '可直接分配', 'ENUM', 0, '派生结果：现有 ComputeGroupQuery 综合持有、预留和有效 GPU 健康/占用观测返回 true/false；不代表申请获批。', 70),
('COMPUTE_GPU_GROUP', 'RESERVED_CARDS', '随组保留卡', 'JSON', 0, '派生结果：组内全部卡减作业使用卡；使用卡来自 allocation_gpu。禁止独立维护或再次分配，完整查询待 M-06。', 80),
('COMPUTE_GPU_GROUP', 'INTERCONNECT', '互联类型', 'STRING', 0, '尚未落库：v0.7 互联类型，不能从 GPU 数量猜测。', 90),
('COMPUTE_GPU_GROUP', 'TOPOLOGY', '拓扑描述', 'STRING', 0, '尚未落库：卡组连接拓扑，后续由资产登记补充。', 100),
('COMPUTE_GPU_DEVICE', 'UUID', 'GPU UUID', 'STRING', 1, '已有字段：gpu_device.gpu_uuid；稳定身份，唯一；Demo 使用样例 UUID，实机必须核对。', 10),
('COMPUTE_GPU_DEVICE', 'GPU_ID', '设备记录编号', 'BIGINT', 1, '已有字段：gpu_device.id；关联使用的内部主键。', 20),
('COMPUTE_GPU_DEVICE', 'GPU_INDEX', '本地卡号', 'NUMBER', 0, '已有字段：gpu_device.gpu_index；与 node_id 组合唯一，不单独代表 GPU 身份。', 30),
('COMPUTE_GPU_DEVICE', 'MODEL', 'GPU 型号', 'STRING', 0, '已有字段：gpu_device.model；资产登记，例如 A800。', 40),
('COMPUTE_GPU_DEVICE', 'VRAM_BYTES', '显存容量', 'BIGINT', 0, '已有字段：gpu_device.vram_bytes；物理显存容量，单位字节，非负，不是当前空闲显存。', 50),
('COMPUTE_GPU_DEVICE', 'HEALTHY', '健康状态', 'ENUM', 0, '关联查询：resource_observation.values_json.healthy，subject_kind=GPU；true/false，未知或过期不能当健康。', 60),
('COMPUTE_GPU_DEVICE', 'OCCUPIED', '实际占用', 'ENUM', 0, '关联查询：resource_observation.values_json.occupied；true/false，与平台预留分别保存。', 70),
('COMPUTE_GPU_DEVICE', 'OBSERVED_AT', '最近采集时间', 'DATE', 0, '关联查询：resource_observation.observed_at；UTC，须核对 valid_until 和观测状态。', 80),
('COMPUTE_DEPLOYMENT', 'IDENTIFIER', '部署名称', 'STRING', 0, '已有字段：deployment.name；展示名，不唯一，不是部署主键。', 10),
('COMPUTE_DEPLOYMENT', 'DEPLOYMENT_ID', '部署记录编号', 'BIGINT', 1, '已有字段：deployment.id；常驻部署的稳定记录主键。', 20),
('COMPUTE_DEPLOYMENT', 'PREEMPTIBLE', '允许抢占', 'ENUM', 0, '已有字段：deployment.preemptible；true/false，还须检查任务等级、对象类型和默认保留限制。', 30),
('COMPUTE_DEPLOYMENT', 'STATUS', '部署业务状态', 'ENUM', 0, '已有字段：deployment.status；当前样例 RUNNING，默认 REGISTERED，退役 RETIRED；v0.7 停服/恢复/故障等流程状态待执行模块落实，不是概念发布状态。', 40),
('COMPUTE_DEPLOYMENT', 'RESOURCE_BASELINE', '资源基线', 'JSON', 0, '关联查询：deployment.current_revision_id → deployment_revision 的 memory_bytes/temporary_bytes/persistent_bytes；单位字节。', 50),
('COMPUTE_DEPLOYMENT', 'RESTORE_CONFIG', '恢复配置', 'JSON', 0, '关联查询：deployment_revision.image_ref/command_args/mounts；抢占流程用 workflow_run.restore_revision_id 固定原版本，不随当前版本变化。', 60),
('COMPUTE_DEPLOYMENT', 'HEALTH_CHECK', '健康检查配置', 'JSON', 0, '关联查询：deployment_revision.health_check；定义启动后如何确认服务可用，尚无真实执行。', 70),
('COMPUTE_DEPLOYMENT', 'REVISION', '当前配置版本', 'NUMBER', 0, '关联查询：deployment.current_revision_id → deployment_revision.version；不同于概念版本。', 80),
('COMPUTE_DEPLOYMENT', 'RESIDENT', '常驻属性', 'ENUM', 0, '派生结果：属于常驻部署类型即为常驻服务；不等于当前正在运行，不新增常驻标记列。', 90),
('COMPUTE_REQUEST', 'IDENTIFIER', '申请编号', 'BIGINT', 1, '已有字段：compute_request.id；唯一记录主键。', 10),
('COMPUTE_REQUEST', 'GPU_COUNT', '申请卡数', 'NUMBER', 0, '已有字段：compute_request.requested_gpu_count；正整数，v0.7 的 1–4 卡进入目标选择，五卡及以上排队，不跨组拼卡。', 20),
('COMPUTE_REQUEST', 'RESOURCE_SPEC', '申请资源规格', 'JSON', 0, '已有字段：compute_request.requested_resource_spec；vramBytesPerGpu/memoryBytes/temporaryBytes/persistentBytes 单位字节，gpuInterconnect 可选；卡数单独存。', 30),
('COMPUTE_REQUEST', 'EFFECTIVE_RESOURCE_SPEC', '生效资源规格', 'JSON', 0, '派生结果：任务类型默认值加申请显式覆盖；实际作业保存 compute_job.effective_resource_spec，不能冒充已实现的默认值合并服务。', 40),
('COMPUTE_REQUEST', 'LAUNCH_SPEC', '启动要求', 'JSON', 0, '已有字段：compute_request.launch_spec；镜像、命令及挂载等申请输入，登记不代表已执行。', 50),
('COMPUTE_REQUEST', 'STATUS', '申请业务状态', 'ENUM', 0, '已有字段：compute_request.status；默认 SUBMITTED，样例 APPROVED；v0.7 的排队/拒绝/取消等由后续流程受控更新，不是概念发布状态。', 60),
('COMPUTE_REQUEST', 'SUBMITTED_AT', '提交时间', 'DATE', 0, '已有字段：compute_request.submitted_at；UTC。', 70),
('COMPUTE_REQUEST', 'CLIENT_REQUEST_KEY', '客户端请求编号', 'STRING', 0, '已有字段：compute_request.client_request_key；同一员工下唯一，与请求指纹一起用于识别重复提交。', 80),
('COMPUTE_REQUEST', 'QUEUED_AT', '排队登记时间', 'DATE', 0, '关联查询：compute_queue.submitted_at；UTC，未排队时可无记录，不等于等待时长。', 90),
('COMPUTE_REQUEST', 'EXPECTED_START_AT', '期望开始时间', 'DATE', 0, '尚未落库：v0.7 期望开始时间；不伪造 compute_request 对应列。', 100),
('COMPUTE_REQUEST', 'EXPECTED_END_AT', '期望结束时间', 'DATE', 0, '尚未落库：v0.7 期望结束时间，不能当实际结束时间。', 110),
('COMPUTE_JOB', 'IDENTIFIER', '作业编号', 'BIGINT', 1, '已有字段：compute_job.id；一次执行尝试的唯一记录主键。', 10),
('COMPUTE_JOB', 'GPU_COUNT', '实际用卡数', 'NUMBER', 0, '已有字段：compute_job.effective_gpu_count；当前业务库限制 1–4，激活时须与使用卡明细数量一致。', 20),
('COMPUTE_JOB', 'RESOURCE_SPEC', '实际资源规格', 'JSON', 0, '已有字段：compute_job.effective_resource_spec；资源量按字节，实际采用的规格，不覆盖原申请。', 30),
('COMPUTE_JOB', 'STATUS', '作业业务状态', 'ENUM', 0, '已有字段：compute_job.status；默认 PENDING，启动/运行/结束等状态待执行模块实现，不是申请批准结果或概念发布状态。', 40),
('COMPUTE_JOB', 'STARTED_AT', '实际开始时间', 'DATE', 0, '已有字段：compute_job.started_at；UTC，尚未开始可为空。', 50),
('COMPUTE_JOB', 'ENDED_AT', '实际结束时间', 'DATE', 0, '已有字段：compute_job.ended_at；UTC，未结束可为空。', 60),
('COMPUTE_JOB', 'RUNTIME_REF', '运行实例引用', 'STRING', 0, '已有字段：compute_job.runtime_ref；运行环境实例引用，完整容器绑定历史待 runtime_binding 实机扩展。', 70),
('COMPUTE_JOB', 'PRIORITY', '调度等级', 'NUMBER', 0, '关联查询：compute_job.task_type_id → task_type.priority；当前两级，实际排队等级另存 compute_queue.priority，未保存作业独立等级快照。', 80),
('COMPUTE_JOB', 'ATTEMPT_NUMBER', '尝试序号', 'NUMBER', 0, '尚未落库：v0.7 尝试序号；作业编号不是同申请的尝试序号。', 90),
('COMPUTE_ALLOCATION', 'IDENTIFIER', '分配编号', 'BIGINT', 1, '已有字段：gpu_allocation.id；唯一主键，同一作业最多一份分配。', 10),
('COMPUTE_ALLOCATION', 'STATUS', '分配业务状态', 'ENUM', 0, '已有字段：gpu_allocation.status；PENDING=待生效、OCCUPIED=占用、RELEASED=释放、CANCELLED=已取消；待生效不持有，前两者计入预留。', 20),
('COMPUTE_ALLOCATION', 'MEMORY_BYTES', '预留内存', 'BIGINT', 0, '已有字段：gpu_allocation.memory_bytes；单位字节，非负。', 30),
('COMPUTE_ALLOCATION', 'TEMPORARY_BYTES', '预留临时存储', 'BIGINT', 0, '已有字段：gpu_allocation.temporary_bytes；单位字节，非负。', 40),
('COMPUTE_ALLOCATION', 'PERSISTENT_BYTES', '预留持久存储', 'BIGINT', 0, '已有字段：gpu_allocation.persistent_bytes；单位字节，非负。', 50),
('COMPUTE_ALLOCATION', 'RESERVED_AT', '预留时间', 'DATE', 0, '已有字段：gpu_allocation.reserved_at；UTC，不代表取得持有权。', 60),
('COMPUTE_ALLOCATION', 'ACTIVATED_AT', '生效时间', 'DATE', 0, '已有字段：gpu_allocation.activated_at；UTC，确认交接后生效。', 70),
('COMPUTE_ALLOCATION', 'CLOSED_AT', '释放或取消时间', 'DATE', 0, '已有字段：gpu_allocation.closed_at；UTC，未关闭可为空。', 80),
('COMPUTE_ALLOCATION', 'CLOSE_REASON', '释放或取消原因', 'STRING', 0, '已有字段：gpu_allocation.close_reason；保留关闭原因。', 90),
('COMPUTE_HOLD_PERIOD', 'IDENTIFIER', '持有区间编号', 'BIGINT', 1, '已有字段：hold_period.id；唯一主键，关闭后不得复用。', 10),
('COMPUTE_HOLD_PERIOD', 'HOLDER', '持有主体', 'JSON', 0, '关联查询：hold_period.deployment_id 或 allocation_id，恰好一个非空；主体是对象关系，不存拼接名字。', 20),
('COMPUTE_HOLD_PERIOD', 'DEPLOYMENT_REVISION', '持有时部署配置', 'NUMBER', 0, '关联查询：hold_period.deployment_revision_id → deployment_revision；部署持有必须指定配置版本，不是当前任意最新版本。', 30),
('COMPUTE_HOLD_PERIOD', 'STARTED_AT', '持有开始时间', 'DATE', 0, '已有字段：hold_period.started_at；UTC，创建后不可修改。', 40),
('COMPUTE_HOLD_PERIOD', 'ENDED_AT', '持有结束时间', 'DATE', 0, '已有字段：hold_period.ended_at；UTC，只允许从空写一次，结束不得早于开始；本次只登记语义，额外防篡改保护属于 M-03。', 50),
('COMPUTE_RULE', 'IDENTIFIER', '规则编号', 'STRING', 0, '已有字段：rule_version.rule_code；跨版本重复，须与 version 组合识别执行版本；对应 bm_rule.rule_code。', 10),
('COMPUTE_RULE', 'VERSION', '规则版本', 'NUMBER', 0, '已有字段：rule_version.version；规则编号加版本唯一，不覆盖旧版。', 20),
('COMPUTE_RULE', 'STAGE', '适用阶段', 'ENUM', 0, '已有字段：rule_version.stage；准入、方案、提交、执行、收尾或全程；具体编码由后续规则模块统一。', 30),
('COMPUTE_RULE', 'RULE_TYPE', '规则类型', 'ENUM', 0, '已有字段：rule_version.rule_type；校验型、规划型、动作型、约束型；不等于规则的发布状态。', 40),
('COMPUTE_RULE', 'DEFINITION', '判定定义', 'JSON', 0, '已有字段：rule_version.definition；程序采用的定义和参数，登记不代表可直接执行任意表达式。', 50),
('COMPUTE_RULE', 'REASON_CODES', '原因码', 'JSON', 0, '已有字段：rule_version.reason_codes；描述失败或分支原因。', 60),
('COMPUTE_RULE', 'OWNER', '规则维护人', 'STRING', 0, '关联查询：rule_version.owner_employee_id → employee；BeModel 概念 owner 是维护角色，不代替实例负责人。', 70),
('COMPUTE_RULE', 'EFFECTIVE_FROM', '生效开始时间', 'DATE', 0, '已有字段：rule_version.effective_from；UTC。', 80),
('COMPUTE_RULE', 'EFFECTIVE_UNTIL', '生效截止时间', 'DATE', 0, '已有字段：rule_version.effective_until；UTC，可空，非空时晚于开始时间。', 90),
('COMPUTE_RULE_CHECK', 'IDENTIFIER', '规则判定编号', 'BIGINT', 1, '已有字段：rule_check.id；唯一主键。', 10),
('COMPUTE_RULE_CHECK', 'RESULT', '规则判定结果', 'ENUM', 0, '已有字段：rule_check.result；PASS/FAIL/NOT_APPLICABLE/ERROR；不是决策 outcome 或动作 status。', 20),
('COMPUTE_RULE_CHECK', 'OUTPUT', '结构化产出', 'JSON', 0, '已有字段：rule_check.output；计划引用、动作引用或分支等，可为空，不把结论只写自然语言。', 30),
('COMPUTE_RULE_CHECK', 'REASON_CODE', '判定原因码', 'STRING', 0, '已有字段：rule_check.reason_code；可追溯的分支或失败原因。', 40),
('COMPUTE_RULE_CHECK', 'RULE_VERSION', '采用的规则版本', 'NUMBER', 0, '关联查询：rule_check.rule_version_id → rule_version；必须保留实际使用版本。', 50),
('COMPUTE_RULE_CHECK', 'KIND', '判定所属阶段', 'ENUM', 0, '关联查询：rule_check.decision_id → decision.kind；ADMISSION/SUBMISSION/CLOSURE，无独立 kind 列。', 60),
('COMPUTE_RULE_CHECK', 'CHECKED_AT', '检查时间', 'DATE', 0, '已有字段：rule_check.checked_at；UTC，不替代决策统一 as_of。', 70),
('COMPUTE_DECISION', 'IDENTIFIER', '决策编号', 'BIGINT', 1, '已有字段：decision.id；唯一主键，历史判断保留。', 10),
('COMPUTE_DECISION', 'KIND', '决策类型', 'ENUM', 0, '已有字段：decision.kind；ADMISSION=准入、SUBMISSION=提交、CLOSURE=收尾。', 20),
('COMPUTE_DECISION', 'OUTCOME', '决策结论', 'ENUM', 0, '已有字段：decision.outcome；准入=通过/不通过，提交=批准/排队/拒绝，收尾=恢复/让位/等待资源；具体编码由后续判定模块落实。', 30),
('COMPUTE_DECISION', 'REASON_CODE', '决策原因码', 'STRING', 0, '已有字段：decision.reason_code；解释本次结论。', 40),
('COMPUTE_DECISION', 'AS_OF', '统一判断时间', 'DATE', 0, '已有字段：decision.as_of；UTC，一次决策一个时间点，所有证据按此核对有效期。', 50),
('COMPUTE_DECISION', 'SNAPSHOT_ID', '证据集合编号', 'BIGINT', 0, '已有字段：decision.snapshot_id；对应 evidence_snapshot，与 as_of 一致。', 60),
('COMPUTE_DECISION', 'TARGET_KIND', '目标类型', 'ENUM', 0, '已有字段：decision.target_kind；与 target_id 同时有值或同时为空，目标可为部署、分配、GPU、卡组等。', 70),
('COMPUTE_DECISION', 'TARGET_ID', '目标记录编号', 'BIGINT', 0, '已有字段：decision.target_id；须与 target_kind 一起解读，不能跨类型直接比较。', 80),
('COMPUTE_DECISION', 'PLAN', '操作计划', 'JSON', 0, '已有字段：decision.plan；v0.7 SchedulePlan 值对象，不单独增加计划概念或任务表。', 90),
('COMPUTE_ACTION', 'IDENTIFIER', '动作编号', 'BIGINT', 1, '已有字段：execution_action.id；一次运行操作的主键，不是 bm_action.action_code。', 10),
('COMPUTE_ACTION', 'ACTION_TYPE', '操作类型', 'ENUM', 0, '已有字段：execution_action.action_type；通知、摘流、停服、启动、停止、恢复等，执行能力后续实现。', 20),
('COMPUTE_ACTION', 'TARGET_KIND', '操作目标类型', 'ENUM', 0, '已有字段：execution_action.target_kind；配合 target_id 引用实际目标。', 30),
('COMPUTE_ACTION', 'TARGET_ID', '操作目标编号', 'BIGINT', 0, '已有字段：execution_action.target_id；不是可直接执行的服务器命令。', 40),
('COMPUTE_ACTION', 'STATUS', '动作执行状态', 'ENUM', 0, '已有字段：execution_action.status；默认 PENDING，业务含待执行/执行中/未知/成功/失败/已补偿；完整编码待执行模块落实，不是规则 result 或概念发布状态。', 50),
('COMPUTE_ACTION', 'IDEMPOTENCY_KEY', '幂等编号', 'STRING', 0, '已有字段：execution_action.idempotency_key；唯一，同一逻辑操作重复请求须核对原结果。', 60),
('COMPUTE_ACTION', 'STARTED_AT', '执行开始时间', 'DATE', 0, '已有字段：execution_action.started_at；UTC。', 70),
